B.Y2=new A.Y(B.r,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.aq_=new A.ee("luna",B.Y2,"scared")
B.XU=new A.Y(B.r,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.aq0=new A.ee("mira",B.XU,"shocked")
